const QV3=(()=>{const V3={bpm:120,kick:'half',kv:0.4,snare:1,clap:1,hat16:0,bassWave:'triangle',bassVol:0.3,bassLP:900,bassPat:[0,null,12,null,0,null,7,12],pad:0,stabs:[1,3],arp:[0,2,1,2,0,2,1,2],arpWave:'triangle',arpVol:0.07,arpLP:4000,leadWave:'square',leadVol:0.05,leadLP:3000,leadLen:0.5,bell:1, chords:[[60,64,67],[55,59,62],[57,60,64],[53,57,60]],roots:[48,43,45,41], mel:[[84,0,79,0,76,79,0,84],[83,0,79,0,74,79,0,83],[81,0,76,0,72,76,0,81],[81,0,77,0,72,77,0,84],[88,0,84,0,79,84,0,88],[86,0,83,0,79,83,0,86],[84,0,81,0,76,81,0,84],[84,0,0,81,77,0,84,0]]}; return V3})();
const QAPPL='data:audio/mpeg;base64,';
const QX=(()=>{
let ctx=null,master=null,mus=null,muted=false;try{muted=localStorage.getItem('quiz.mute')==='1'}catch{}
function unlock(){try{if(!ctx){const A=window.AudioContext||window.webkitAudioContext;if(!A)return;ctx=new A();master=ctx.createGain();master.gain.value=muted?0:0.9;master.connect(ctx.destination)}if(ctx.state==='suspended')ctx.resume().then(()=>{try{watch(true)}catch{}}).catch(()=>{});loadApp();renderMusic()}catch{}}
['pointerdown','pointerup','click','keydown','touchstart','touchend'].forEach(e=>addEventListener(e,unlock,{passive:true,capture:true}));
function ready(){return ctx&&ctx.state==='running'&&!muted}
function stopMusic(){if(mus){clearTimeout(mus.t);const sr_=mus.src;setTimeout(()=>{try{sr_&&sr_.stop()}catch{}},650);try{mus.g.gain.cancelScheduledValues(0);mus.g.gain.setTargetAtTime(0,ctx.currentTime,0.08)}catch{}const g=mus.g;setTimeout(()=>{try{g.disconnect()}catch{}},600);mus=null}}
let musicOn=true;try{musicOn=localStorage.getItem('quiz.music')!=='0'}catch{}
function setMusic(v){musicOn=v;try{localStorage.setItem('quiz.music',v?'1':'0')}catch{}if(!v)stopMusic();btn();watch(true)}
let musBuf=null,musRender=null;
function renderMusic(){if(musBuf||musRender||!ctx)return musRender;const sr=44100,V=QV3,len=Math.ceil((8*4*60/V.bpm+2.5)*sr);let oc;try{oc=new (window.OfflineAudioContext||window.webkitOfflineAudioContext)(2,len,sr)}catch{return null}
 musRender=(async()=>{try{const g=oc.createGain();g.gain.value=1;g.connect(oc.destination);QS.music2(oc,g,QV3);const r=await oc.startRendering();const loopLen=Math.round(8*4*60/V.bpm*sr);const out=ctx.createBuffer(2,loopLen,sr);for(let ch=0;ch<2;ch++){const src=r.getChannelData(ch),dst=out.getChannelData(ch);for(let i=0;i<loopLen;i++)dst[i]=src[i];const tail=src.length-loopLen;for(let i=0;i<tail&&i<loopLen;i++)dst[i]+=src[loopLen+i]}musBuf=out;try{watch(true)}catch{}}catch{musRender=null}})();return musRender}
function startMusic(){if(mus||!ready()||!musicOn)return;if(!musBuf){renderMusic();return}const g=ctx.createGain();g.gain.value=0.85;g.connect(master);const src=ctx.createBufferSource();src.buffer=musBuf;src.loop=true;src.connect(g);src.start();mus={g,src,t:0}}
function once(fn){if(ready()){try{fn(ctx,master,ctx.currentTime+0.03)}catch{}}}
function setMuted(v){muted=v;try{localStorage.setItem('quiz.mute',v?'1':'0')}catch{}if(master)master.gain.value=v?0:0.9;if(v)stopMusic();btn();watch(true)}
let appBuf=null,appLoading=false;function loadApp(){if(appBuf||appLoading||!ctx)return;appLoading=true;Promise.resolve().then(()=>{const bin=atob(QAPPL.split(',')[1]),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);return ctx.decodeAudioData(u.buffer)}).then(b=>{appBuf=b}).catch(()=>{appLoading=false})}
function playApp(){try{const src=ctx.createBufferSource();src.buffer=appBuf;const g=ctx.createGain();g.gain.value=0.8;src.connect(g);g.connect(master);src.start()}catch{}}
function applause(){if(muted||!ctx)return;if(appBuf){if(ctx.state==='running')playApp();else ctx.resume().then(playApp).catch(()=>{});return}
 loadApp();let n=0;const w=setInterval(()=>{n++;if(appBuf){clearInterval(w);if(!muted)playApp()}else if(n>40){clearInterval(w);try{const a=new Audio(QAPPL);a.volume=1;if(!muted)a.play().catch(()=>{})}catch{}}},150)}
function confetti(){const box=document.createElement('div');box.className='qconf';const cols=['#E60000','#ffffff','#ff6b6b','#ffd166','#4cc38a'];for(let i=0;i<70;i++){const p=document.createElement('i');p.style.left=Math.random()*100+'%';p.style.background=cols[i%cols.length];p.style.animationDelay=Math.random()*1.2+'s';p.style.animationDuration=2.4+Math.random()*2+'s';p.style.setProperty('--dx',(Math.random()*160-80)+'px');box.appendChild(p)}document.body.appendChild(box);setTimeout(()=>box.remove(),6500)}
function mstate(){if(muted)return 'off';if(!musicOn)return 'off';if(!ctx||ctx.state!=='running')return 'blocked';return mus?'playing':'waiting'}
function btn(){let b=document.getElementById('qmute');const on=(role==='quiz'&&Q.view==='host')||role==='quizPlay';if(!on){if(b)b.remove();return}if(!b){b=document.createElement('button');b.id='qmute';b.type='button';b.className='secondary';b.onclick=()=>{unlock();setMuted(!muted)};document.body.appendChild(b)}b.textContent=muted?'🔇':'🔊';if(role==='quiz'&&Q.view==='host'){let m=document.getElementById('qmusic');if(!m){m=document.createElement('button');m.id='qmusic';m.type='button';m.className='secondary';m.onclick=()=>{unlock();if(muted){setMuted(false);setMusic(true)}else if(!musicOn)setMusic(true);else if(mstate()!=='blocked')setMusic(false);else btn()};document.body.appendChild(m)}const ms=mstate();m.dataset.state=ms;m.textContent='🎵 '+t(ms==='playing'?'الموسيقى: شغّالة':ms==='waiting'?'الموسيقى: هتشتغل مع السؤال':ms==='blocked'?'الموسيقى: دوس هنا عشان الصوت يشتغل':'الموسيقى: مقفولة');m.title=m.ariaLabel=t(mstate()==='off'?'شغّل الموسيقى':'وقف الموسيقى')}else{const m=document.getElementById('qmusic');if(m)m.remove()}b.title=b.ariaLabel=t(muted?'شغّل الصوت':'اكتم الصوت')}
let last=null;
function watch(force){btn();const s=Q.gs,host=role==='quiz'&&Q.view==='host',pl=role==='quizPlay';if(!s||!(host||pl)){stopMusic();last=null;return}
 const key=s.code+'|'+s.phase+'|'+s.qi+'|'+(pl?'p':'h');
 if(host){if(s.phase==='answering')startMusic();else stopMusic()}else stopMusic();
 if(key===last&&!force)return;const prev=last;last=key;if(!force&&prev&&(s.phase==='answering'||s.phase==='reveal')){try{window.scrollTo({top:0,behavior:'smooth'})}catch{}}if(force||!prev)return;if(prev.split('|')[0]!==key.split('|')[0])return;
 if(s.phase==='reveal'&&pl&&s.me&&s.me.answered&&s.q&&s.q.type!=='cloud'){once(s.me.ok?QS.ting:QS.buzz)}
 if(s.phase==='ended'){applause();confetti()}}
setInterval(()=>watch(false),400);
return {unlock,watch}})();
/* hints */
{const H={edit:'اكتب الأسئلة، حدّد الإجابة الصح، وبعدين احفظ.',lib:'اختار كويز وابدأه، أو اعمل واحد جديد.',launch:'اختار شكل اللعب: فردي أو فرق.'};
const HP={lobby:'شارك الكود أو الـQR، واضغط ابدأ لما الكل يدخل.',answering:'اللاعبين بيجاوبوا دلوقتي. تقدر تعرض النتيجة بدري.',reveal:'دي الإجابة والترتيب. اضغط التالي لما تبقى جاهز.',ended:'الكويز خلص. صدّر النتايج أو ارجع للمكتبة.'};
const _qr=qrender;qrender=function(){_qr();if(role!=='quiz')return;const r=$('quizRoot');if(!r)return;let k=H[Q.view];if(Q.view==='host'&&Q.gs)k=HP[Q.gs.phase];if(!k)return;const old=r.querySelector('.qhint');if(old)old.remove();const p=document.createElement('p');p.className='qhint';p.textContent=t(k);r.insertBefore(p,r.firstChild)}}
/* autosave of drafts */
{const key=()=>'quiz.draft.'+(Q.draftId||'new');let tm=0;
const save=()=>{if(role!=='quiz'||Q.view!=='edit'||!Q.draft||Q._base==null)return;try{const cur=JSON.stringify(Q.draft);if(cur===Q._base)localStorage.removeItem(key());else localStorage.setItem(key(),JSON.stringify({base:Q._base,cur}))}catch{}};
const sched=()=>{clearTimeout(tm);tm=setTimeout(save,500)};
const _ev=editView;editView=function(r){if(Q._dr!==Q.draft){Q._dr=Q.draft;Q._base=JSON.stringify(Q.draft);try{const s=JSON.parse(localStorage.getItem(key())||'null');if(s&&s.base===Q._base&&s.cur!==Q._base){Q.draft=Q._dr=JSON.parse(s.cur);qtoast(t('رجّعنا تعديلاتك اللي ما اتحفظتش.'),{label:t('ابدأ من جديد'),fn:()=>{try{localStorage.removeItem(key())}catch{}Q.draft=Q._dr=JSON.parse(Q._base);editView($('quizRoot'))}})}}catch{}}_ev(r);sched()};
addEventListener('input',e=>{if(role==='quiz'&&Q.view==='edit'&&e.target.closest&&e.target.closest('#quizRoot'))sched()},true);
addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});
const _api=qapi;qapi=async function(p,b,tok){const k=key(),res=await _api(p,b,tok);if(p==='/library/save'){try{localStorage.removeItem(k)}catch{}}return res}}
function qtoast(msg,act){const old=document.getElementById('qtoast');if(old)old.remove();const d=document.createElement('div');d.id='qtoast';d.setAttribute('role','status');const s=document.createElement('span');s.textContent=msg;d.appendChild(s);if(act){const a=document.createElement('button');a.type='button';a.className='secondary';a.textContent=act.label;a.onclick=()=>{act.fn();d.remove()};d.appendChild(a)}const x=document.createElement('button');x.type='button';x.className='secondary';x.textContent='✕';x.setAttribute('aria-label','close');x.onclick=()=>d.remove();d.appendChild(x);document.body.appendChild(d);setTimeout(()=>d.remove(),5000)}
